import{_ as a,o as t,c as n,a3 as r}from"./chunks/framework.BlfGB29P.js";const h=JSON.parse('{"title":"Leave Management — User Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Leave Management — User Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/leave-management"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Leave Management — User Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/leave-management"}]]},"headers":[],"relativePath":"user-guide/leave-management.md","filePath":"user-guide/leave-management.md","lastUpdated":1787349040000}'),s={name:"user-guide/leave-management.md"};function o(l,e,i,d,c,p){return t(),n("div",null,[...e[0]||(e[0]=[r(`<h1 id="leave-management-—-user-guide" tabindex="-1">Leave Management — User Guide <a class="header-anchor" href="#leave-management-—-user-guide" aria-label="Permalink to &quot;Leave Management — User Guide&quot;">​</a></h1><p>Enable <strong>Employees</strong> first, then install <strong>Leave Management</strong> from Marketplace (free). Nav appears under <strong>HR</strong>.</p><h2 id="leave-types" tabindex="-1">Leave types <a class="header-anchor" href="#leave-types" aria-label="Permalink to &quot;Leave types&quot;">​</a></h2><p>Admins (and workspace owners) manage leave types. Staff and managers can view types when submitting requests, but cannot create or edit them.</p><ol><li>Create types such as Annual Leave or Sick Leave with a unique code.</li><li>Set whether the leave is paid, the annual allowance, and whether the type is active.</li><li>Inactive types stay in history but should not be used for new requests.</li></ol><h2 id="balances" tabindex="-1">Balances <a class="header-anchor" href="#balances" aria-label="Permalink to &quot;Balances&quot;">​</a></h2><p>Admins (and workspace owners) manage entitled balances. Staff see only their own balances; managers can view balances when reviewing leave.</p><ol><li>Upsert a balance for an employee + leave type + calendar year.</li><li>Set <strong>entitled</strong> days (and optional <strong>used</strong>); <strong>remaining</strong> is kept in sync (<code>entitled − used</code>).</li><li>Approving a leave request increases <strong>used</strong> (and decreases remaining) for that year.</li></ol><h2 id="who-can-submit" tabindex="-1">Who can submit <a class="header-anchor" href="#who-can-submit" aria-label="Permalink to &quot;Who can submit&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>Create / submit</th></tr></thead><tbody><tr><td>Staff</td><td>Own linked active employee only</td></tr><tr><td>Manager</td><td>Own linked active employee only</td></tr><tr><td>Admin / Superadmin</td><td>Any employee</td></tr></tbody></table><p>Staff lists show only their own requests. Managers and admins see everyone’s requests so they can review pending items.</p><h2 id="leave-requests" tabindex="-1">Leave requests <a class="header-anchor" href="#leave-requests" aria-label="Permalink to &quot;Leave requests&quot;">​</a></h2><ol><li>Create a <strong>draft</strong> request with leave type and start/end dates (days default from the inclusive date span when omitted). Non-admins are locked to themselves.</li><li><strong>Submit</strong> moves the request to <strong>pending</strong>.</li><li>Approvers with <code>leave-management.approve</code> can <strong>Approve</strong> or <strong>Reject</strong>: <ul><li><strong>Reject</strong> requires review notes.</li><li><strong>Approve</strong> lets you choose <strong>Deduct salary</strong> (default: deduct when the leave type is unpaid). Overriding that default requires review notes.</li></ul></li><li>Drafters can <strong>Cancel</strong> their own draft or pending requests (admins may cancel for others).</li><li>Only drafts are editable; soft-deleted requests can be restored when permitted.</li></ol><h2 id="workflow" tabindex="-1">Workflow <a class="header-anchor" href="#workflow" aria-label="Permalink to &quot;Workflow&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>draft → pending → approved | rejected</span></span>
<span class="line"><span>draft | pending → cancelled</span></span></code></pre></div><p>Approved, rejected, and cancelled are terminal.</p><h2 id="payroll-note" tabindex="-1">Payroll note <a class="header-anchor" href="#payroll-note" aria-label="Permalink to &quot;Payroll note&quot;">​</a></h2><p>When Payroll is installed, approved leave with <strong>Deduct salary</strong> reduces that employee’s pay-run net (legacy approved rows without the flag treat unpaid types as deductible).</p>`,18)])])}const u=a(s,[["render",o]]);export{h as __pageData,u as default};
